import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfAluno = () => {
  const { id } = useParams();
  const [aluno, setAluno] = useState(null);
  const [curso, setCurso] = useState(null);
  const [listaCursos, setListaCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [editMode, setEditMode] = useState(false);

  useEffect(() => {
    const fetchAluno = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAluno(dados);
          setCurso(dados.curso);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchCursos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setListaCursos(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de cursos:", error);
      }
    };

    fetchAluno();
    fetchCursos();
  }, [id]);

  const adicionarCurso = async () => {
    if (!cursoSelecionado) return;

    try {
      const resposta = await fetch(`http://localhost:5000/alunos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ curso: cursoSelecionado }),
      });

      if (resposta.ok) {
        setCurso(cursoSelecionado);
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!aluno) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{aluno.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={() => setEditMode(true)}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informação do Aluno</h4>
          <p>
            <strong>{aluno.nome}</strong>
          </p>
          <p>{aluno.email}</p>
          <p>{aluno.morada}</p>
          <p>{aluno.contacto}</p>
        </div>

        <div className="w-50 ps-4">
          <label className="fw-bold">Curso a Frequentar</label>
          {curso ? (
            <p className="text-success text-center mt-3">
              <strong>{curso}</strong>
            </p>
          ) : (
            <div>
              <select
                className="form-control mb-2"
                value={cursoSelecionado}
                onChange={(e) => setCursoSelecionado(e.target.value)}
                disabled={!editMode}
              >
                <option value="">Selecione um curso</option>
                {listaCursos.map((c) => (
                  <option key={c.id} value={c.nome}>
                    {c.nome}
                  </option>
                ))}
              </select>
              {editMode && (
                <div className="d-flex justify-content-between mt-3">
                  <button
                    className="btn btn-danger"
                    onClick={() => setEditMode(false)}
                  >
                    Cancelar
                  </button>
                  <button className="btn btn-primary" onClick={adicionarCurso}>
                    Salvar
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfAluno;
